  15	pub(super) fn tunnel_duration(mut remaining: i64, speed: i64, from_speed: bool) -> f64 {
  16	    let mut ticks = 0;
  17	    let reached = if from_speed { speed } else { 1000 };
  18	    while remaining > 0 {
  19	        ticks += 1;
  20	        let mut budget = speed;
  21	        while budget > 0 {
  22	            let substep = budget.min(250);
  23	            remaining = (remaining - substep).max(0);
  24	            if remaining <= reached {
  25	                remaining = 0;
  26	                break;
  27	            }
  28	            budget -= substep;
  29	        }
  30	    }
  31	    ticks as f64 * 0.05
  32	}
